<?php require_once __DIR__.'/includes/permissions.php';require_permission('audit.view');$rows=db()->query('SELECT al.*,u.staff_id,u.full_name FROM audit_logs al LEFT JOIN users u ON u.id=al.user_id ORDER BY al.created_at DESC LIMIT 500')->fetchAll();include __DIR__.'/includes/header.php';?><div class="page-head"><div><h1>Audit Logs</h1><p>Administrative trace of security-sensitive actions.</p></div></div><div class="panel"><div class="table-responsive"><table class="table small"><thead><tr><th>Date/Time</th><th>User</th><th>Action</th><th>Entity</th><th>ID</th><th>Description</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e(($r['staff_id']??'System').' / '.($r['full_name']??''))?></td><td><?=e($r['action'])?></td><td><?=e($r['entity'])?></td><td><?=e((string)$r['entity_id'])?></td><td><?=e($r['description'])?></td><td><?=e($r['ip_address'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/includes/footer.php'; ?>
